import {dayKey,timeKey,shiftDay,localStamp,emptyState,summary,periodSummary,parseBackup,validateState,elapsedMinutes,weightChange,kinds,monthDeadline,dailyStepGoal,stepProgress,fastingPlanMinutes,fastingProgress,sleepStageNames,sleepStageSummary} from './model.js';
import {readState,writeState,compressPhoto} from './db.js';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>Number(n).toLocaleString('en-IN',{maximumFractionDigits:d});const dateLabel=d=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'}).format(new Date(d+'T12:00:00+05:30'));
const paths={leaf:'M20 4C9 2 3 8 5 15c4 8 16 3 15-11ZM5 20 15 9',today:'M3 10h18M7 3v4m10-4v4M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Z',trends:'M4 20V4m0 16h17M7 14l4-4 4 2 5-7',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-5v6l4 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3l-1 3-3 1-2 3 2 2-1 4 3 2 3-1 2 3 3-1 1-3 3-1 2-3-2-2 1-4-3-2-3 1-2-3Z',plus:'M12 5v14M5 12h14',food:'M4 3v7m4-7v7m-6-3h8m-4 3v11M17 3v18m0-18c6 2 5 10 0 10',walk:'M13 3a1 1 0 1 0 0 .1M10 8l3-2 3 5 4 1M5 12l5-4-1 7-4 6m4-6 5 1 3 5',water:'M12 3C9 8 5 12 5 15a7 7 0 0 0 14 0c0-3-4-7-7-12Z',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z',weight:'M5 5h14a2 2 0 0 1 2 2v12H3V7a2 2 0 0 1 2-2Zm3 3h8m-4 0 2 4',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2',check:'M5 12l4 4L19 6',shield:'M12 3l8 4v6c0 5-8 8-8 8s-8-3-8-8V7l8-4Zm-4 9 3 3 5-6',arrow:'M5 12h14m-5-5 5 5-5 5',strength:'M3 8v8m4-10v12m0-6h10m0-6v12m4-10v8',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-6v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
const button=(text,action,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
let state,view='today',selectedDay=dayKey(),historyKind='all',historyDate='',saveQueue=Promise.resolve(),dialogContext=null;
const changes=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('steadily-changes'):null;
changes?.addEventListener('message',async()=>{try{const saved=await readState();if(saved){state=validateState(saved);render();}}catch(e){toast('Could not refresh this journal: '+e.message);}});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function commit(update){const work=saveQueue.then(async()=>{const save=async()=>{const next=structuredClone(await readState()||state);await update(next);validateState(next);await writeState(next);state=next;render();changes?.postMessage('saved');};if(navigator.locks)await navigator.locks.request('steadily-write',save);else await save();});saveQueue=work.catch(()=>{});try{await work;return true;}catch(e){toast(`Could not save: ${e.message}. Export a backup if storage is full.`);return false;}}
function shell(){return `<aside class="sidebar"><a class="brand" href="#today">${icon('leaf')}<span>steadily<span class="brand-dot">.</span></span></a><p class="brand-sub">A LITTLE BETTER, EVERY DAY</p><nav aria-label="Main navigation">${['today','trends','history','settings'].map(v=>`<button data-view="${v}" class="nav-item ${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(v)}<span>${v[0].toUpperCase()+v.slice(1)}</span>${v===view?'<i></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="journey-art">${icon('leaf')}<span>Good choices.<br>Lasting habits.</span></div><div class="privacy">${icon('shield')}<span>Just you and your progress.<small>Saved on this device</small></span></div></div></aside><main id="main"><header class="topbar"><div class="topbar-identity"><span class="mobile-brand">${icon('leaf')}steadily<span class="brand-dot">.</span></span><span class="topbar-motto">A LITTLE BETTER, EVERY DAY</span></div><span class="local-badge">${icon('shield')} Private & local</span></header>${view==='today'?todayView():view==='trends'?trendsView():view==='history'?historyView():settingsView()}<footer>Build habits that fit your life.<span>Asia/Kolkata · <span id="connection">${navigator.onLine?'On this device':'Offline · ready to log'}</span></span></footer></main><nav class="mobile-nav" aria-label="Mobile navigation">${['today','trends','history','settings'].map(v=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(v)}<span>${v[0].toUpperCase()+v.slice(1)}</span></button>`).join('')}</nav>`;}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><p class="eyebrow">${view==='today'?new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long',timeZone:'Asia/Kolkata'}).format(new Date(selectedDay+'T12:00:00+05:30')):'YOUR PROGRESS, IN PERSPECTIVE'}</p><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function cardTitle(name,i,action=''){return `<div class="card-title"><h2>${icon(i)}${name}</h2>${action}</div>`;}
function bar(value,goal){return `<div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="${goal}" aria-valuenow="${Math.min(value,goal)}" aria-label="Progress"><span style="width:${Math.min(100,value/goal*100)}%"></span></div>`;}
function movementCard(s){
 const p=stepProgress(state,selectedDay);
 return `<article class="card movement-card priority-movement" aria-labelledby="movement-heading">
  <div class="card-title"><h2 id="movement-heading">${icon('walk')} Movement</h2><span class="priority-pill">TODAY’S FOCUS</span></div>
  <div class="step-overview"><div><span class="metric-label">Steps today</span><button class="step-count" data-action="steps" aria-label="Log or edit today’s steps">${p.steps===undefined?'—':fmt(p.steps)}</button></div><div><span class="metric-label">Daily step goal</span><button class="step-goal" data-action="step-goal" aria-label="Edit daily step goal"><strong>${fmt(p.goal)}</strong><span>Edit goal ${icon('plus')}</span></button></div></div>
  <div class="step-progress" role="progressbar" aria-label="Today’s step goal progress" aria-valuemin="0" aria-valuemax="${p.goal}" aria-valuenow="${Math.min(p.steps??0,p.goal)}" aria-valuetext="${p.steps===undefined?'Steps not logged':`${p.steps} of ${p.goal} steps`}"><span style="width:${p.percent}%"></span></div>
  <p class="step-progress-copy">${p.steps===undefined?'Log your steps to see today’s progress.':p.remaining===0?'Your step goal is reached. Choose what feels right next.':`${fmt(p.remaining)} steps to your personal goal · ${Math.round(p.percent)}% logged`}</p>
  <div class="movement-actions">${button(icon('walk')+' Start a walk','movement','primary')}${button('Log steps','steps','secondary')}${button('Log exercise','new:exercise','secondary')}</div>
  <div id="movement-live"></div>
  <div class="activity-summary"><span><strong>${s.exerciseMinutes}</strong> min exercise logged</span><span><strong>${s.movements.length}</strong> post-meal moves</span></div>
  <p class="source-label">Steps & exercise: manually entered from Apple Health / Apple Watch.</p>
 </article>`;
}
function fastPlanCopy(p){
 if(!p.active)return p.target?`Your optional plan is ${duration(p.target)}. Start when you choose.`:'No planned duration. You can record a fast without a target.';
 if(p.target===null)return 'No duration target. You can end your fast at any time.';
 if(p.reached)return 'Planned window reached. Choose whether to end now.';
 return `${duration(p.remaining)} remaining in your plan. You can end earlier.`;
}
function fastingCard(){
 const p=fastingProgress(state);
 const last=state.fasts.slice().sort((a,b)=>a.end.localeCompare(b.end)).at(-1);
 return `<article class="card fasting-card priority-fasting" aria-labelledby="fasting-heading">
  ${cardTitle('Fasting window','clock',button('Edit schedule','fast-schedule','secondary compact-action')).replace('<h2>','<h2 id="fasting-heading">')}
  <div class="fast-status"><span class="status-dot ${p.active?'live':''}"></span>${p.active?'Fast in progress · live now':'No active fast'}<span class="optional-tag">OPTIONAL</span></div>
  <div class="fast-time-row"><div><span class="metric-label">${p.active?'Elapsed time':'Live timer'}</span><strong id="fast-clock" class="large-value">${p.active?timerDuration(p.elapsed):'—'}</strong></div><div><span class="metric-label">Planned duration</span><strong class="fast-target">${p.target?duration(p.target):'No target'}</strong></div></div>
  <div class="fast-plan-track" role="progressbar" aria-label="Planned fasting window progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.floor(p.percent)}" aria-valuetext="${p.active&&p.target?Math.floor(p.percent)+'% of planned duration':'No active planned fast'}" ${p.target===null?'hidden':''}><span id="fast-progress-fill" style="width:${p.percent}%"></span></div>
  <p id="fast-plan-note" class="fast-plan-note" role="status">${fastPlanCopy(p)}</p>
  ${state.settings.fastingOptional?`<p class="eating-schedule">Eating window <strong>${clock12(state.settings.eatingStart)} – ${clock12(state.settings.eatingEnd)}</strong></p>`:'<p class="eating-schedule">Eating-window reference is off.</p>'}
  <div class="button-row">${button(p.active?'End fast':'Start fast',p.active?'fast-end':'fast-start','primary')}${p.active?button('Edit start','fast-edit','text-button'):''}${button('Fasting history','fast-history','text-button')}</div>
  ${last?`<p class="source-label">Last completed: ${duration(elapsedMinutes(last.start,last.end))} · ${dateLabel(last.date)}</p>`:''}
  <p class="source-label">Follow your own rhythm. Ending early is always an option; longer fasts do not affect your consistency score.</p>
 </article>`;
}
function sleepStagesView(record){
 const stages=sleepStageSummary(record);
 if(!stages)return '';
 return `<div class="sleep-stages"><h3>Sleep stages <span>Manual entries</span></h3>
  ${stages.logged>0?`<div class="stage-track" role="img" aria-label="Manually entered sleep stages: ${stages.entries.map(e=>`${e.name} ${e.minutes} minutes`).join(', ')}${stages.unentered?', with unentered time shown separately':''}">${stages.entries.filter(e=>e.minutes>0).map(e=>`<span class="stage-${e.key}" style="width:${e.minutes/stages.total*100}%" title="${e.name}: ${e.minutes} min"></span>`).join('')}${stages.unentered?`<span class="stage-unentered" style="width:${stages.unentered/stages.total*100}%" title="Stage not entered"></span>`:''}</div>`:''}
  <dl class="stage-legend">${Object.entries(sleepStageNames).map(([key,name])=>`<div><dt><i class="stage-${key}" aria-hidden="true"></i>${name}</dt><dd>${Object.hasOwn(record.stages,key)?duration(record.stages[key]):'Not entered'}</dd></div>`).join('')}</dl>
  <p class="source-label">${stages.unentered?'Hatched space means stage data not entered. ':''}Only your manual entries are shown. Missing stages are never estimated.</p>
 </div>`;
}
function sleepCard(sleep){
 return `<article class="card sleep-card priority-sleep" aria-labelledby="sleep-heading">
 ${cardTitle('Sleep & recovery','moon',button(sleep?'Edit sleep':'Log sleep',sleep?'edit:sleep':'new:sleep','secondary compact-action',sleep?`data-id="${sleep.id}"`:'')).replace('<h2>','<h2 id="sleep-heading">')}
 <span class="metric-label">Previous night’s sleep</span><strong class="large-value">${sleep?`${Math.floor(sleep.minutes/60)}<small> h </small>${sleep.minutes%60}<small> min</small>`:'—<small> hours</small>'}</strong>
 <p>${sleep?`${esc(sleep.quality||'Quality not specified')} · waking date ${dateLabel(sleep.date)}`:'Log your sleep when you’re ready.'}</p>
 ${sleepStagesView(sleep)}
 ${!sleepStageSummary(sleep)?'<p class="area-microcopy">Optional REM, Core, Deep, and Awake entries are available in the sleep form.</p>':''}
 <p class="source-label">Manually entered from Apple Health / Apple Watch. No automatic sync.</p>
 </article>`;
}
function todayView(){
 const s=summary(state,selectedDay);
 const last=state.weights.filter(w=>w.date<=selectedDay).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);
 const sleep=s.sleep.at(-1);
 const remain=[!s.meals.length&&'A meal log',s.daily.steps===undefined&&'Today’s steps',!s.sleep.length&&'Last night’s sleep'].filter(Boolean);
 return `<div class="today-heading">${heading(selectedDay===dayKey()?'Your day, your way.':'A day worth noticing.','Movement first. One good choice at a time.',`<label class="date-picker">Viewing day<input aria-label="Viewing day" type="date" id="selected-day" value="${selectedDay}" max="${dayKey()}"></label>`)}</div>
 <div class="today-flow">
  <section class="priority-section movement-section" aria-label="Movement">${movementCard(s)}</section>
  <section class="priority-section food-section" aria-labelledby="food-heading"><div class="section-heading"><h2 id="food-heading">Food & water</h2><span>Fuel, hydrate, and keep your day in view.</span></div>
  <section class="nutrition-grid"><article class="stat-card peach"><span>${icon('food')} Calories</span><strong>${fmt(s.calories)}<small> kcal</small></strong><p>Manually entered estimates</p></article><article class="stat-card sage"><span>${icon('strength')} Protein</span><strong>${fmt(s.protein,1)}<small> g</small></strong>${bar(s.protein,state.settings.proteinGoal)}<p>Personal reference · ${state.settings.proteinGoal} g</p></article><article class="stat-card lavender"><span>${icon('leaf')} Fiber</span><strong>${s.hasFiber?fmt(s.fiber,1):'—'}<small> g</small></strong><p>${s.hasFiber?'From your meal estimates':'Optional · log when you know'}</p></article><article class="stat-card cream"><span>${icon('today')} Meals</span><strong>${s.meals.length}<small> logged</small></strong><p>${s.meals.length?'Your nourishment, noted':'Ready for your first entry'}</p></article></section>
  <div class="food-water-grid"><article class="card meals-card">${cardTitle('Fuel your day','food',button('Add meal +','new:meals','primary compact-action'))}<p class="muted">Log what you eat. Learn what fuels you.</p>${s.meals.length?`<div class="meal-list">${s.meals.map(m=>`<div class="meal-row">${m.photo?`<img class="meal-photo" src="${m.photo}" alt="Attachment for ${esc(m.name)}">`:`<span class="meal-placeholder">${icon('food')}</span>`}<button class="meal-info" data-action="edit:meals" data-id="${m.id}"><strong>${esc(m.name)}</strong><span>${esc(m.time)} · ${fmt(m.calories)} kcal · ${fmt(m.protein,1)} g protein</span></button><button class="favorite ${m.favorite?'selected':''}" data-action="favorite" data-id="${m.id}" aria-label="${m.favorite?'Unfavorite':'Favorite'} ${esc(m.name)}">${m.favorite?'★':'☆'}</button></div>`).join('')}</div>`:`<div class="empty-meals">${icon('food')}<h3>Make your next meal count.</h3><p>Your next meal is your next chance to nourish yourself.</p>${button('Log your first meal','new:meals','secondary')}</div>`}<div class="quick-foods"><span class="eyebrow">QUICK ADD</span><div>${state.settings.foods.slice(0,5).map((f,i)=>button(esc(f.name),`food:${i}`,'chip')).join('')}${button('All foods '+icon('arrow'),'foods','chip')}</div></div><div class="meal-shortcuts">${button('Recent meals','recent','text-button')}${button('★ Favorites','favorites','text-button')}</div></article><article class="card water-card">${cardTitle('Hydrate','water',button('Edit','water-history','text-button'))}<div class="water-visual"><div class="water-drop">${icon('water')}</div><div><strong>${fmt(s.waterTotal)}<small> ml</small></strong><p>of your ${fmt(state.settings.waterGoal)} ml reference</p></div></div>${bar(s.waterTotal,state.settings.waterGoal)}<p class="area-microcopy">Small sips add up.</p><div class="water-actions">${button('+ 250 ml','water:250','primary')}${button('+ 500 ml','water:500','secondary')}${button('Custom','new:water','text-button')}</div>${button('↶ Undo latest','water-undo','text-button',s.water.length?'':'disabled')}</article></div></section>
  <section class="priority-section fasting-section" aria-label="Fasting">${fastingCard()}</section>
  <section class="priority-section sleep-section" aria-label="Sleep and recovery">${sleepCard(sleep)}</section>
  <section class="priority-section remaining-section" aria-labelledby="remaining-heading"><div class="section-heading"><h2 id="remaining-heading">The rest of your rhythm</h2><span>Your other habits, reflections, and longer view.</span></div><div class="remaining-grid">
  <article class="card sugar-card">${cardTitle('No added sugar','leaf')}<label class="toggle-line"><span><strong>No added sugar today</strong><small>Awareness first. No judgment.</small></span><input id="sugar-toggle" type="checkbox" ${s.daily.sugar===true?'checked':''}><span class="toggle" aria-hidden="true"></span></label><p class="muted">${s.daily.sugar===undefined?'Not checked in yet.':s.daily.sugar?'Logged — awareness in action.':'Noted. Use this to understand your patterns.'}</p><div class="spread">${button('Add a note','sugar-note','text-button')}${button('Log a craving','new:cravings','text-button')}</div>${s.daily.sugarNote?`<p class="note">${esc(s.daily.sugarNote)}</p>`:''}${s.cravings.length?`<p class="muted">${s.cravings.length} craving / snack observation${s.cravings.length===1?'':'s'} saved.</p>`:''}</article>
  <article class="card rhythm-summary">${cardTitle('Your daily rhythm','leaf')}<div class="rhythm-total"><strong>${s.score}<small>%</small></strong><span>${s.completed} of ${s.habitCount} areas logged</span></div>${bar(s.completed,s.habitCount)}<p>${s.completed?'You are building your rhythm, one choice at a time.':'Start with one action. The rest gets easier.'}</p><p class="source-label">Based on logs and habits, never on low calories or longer fasting.</p></article>
  <article class="card weight-card">${cardTitle('Your weight journey','weight',button('Log weight +','new:weights','secondary compact-action'))}<div class="weight-numbers"><div><strong>${last?fmt(last.kg,1):fmt(state.settings.startWeight,1)}<small> kg</small></strong><span>${last?'Latest · '+dateLabel(last.date):'Starting reference · editable'}</span></div><span class="weight-line"></span><div><strong>${fmt(state.settings.goalWeight,1)}<small> kg</small></strong><span>Your long-term direction</span></div></div>${weightChart()}<p class="area-microcopy">${fmt(state.settings.goalWeight,1)} kg is the direction. Today is the work.</p><p class="muted">${last?'Look at the trend, beyond a single day.':'Log your first weight to begin your trend.'}</p></article><article class="card review-card">${cardTitle('Daily check-in','sun')}<p class="muted">Notice what worked. Choose one good next step.</p><div class="review-buttons">${button(icon('sun')+' Morning overview','morning','secondary')}${button(icon('moon')+' Evening review','evening','secondary')}</div>${state.settings.reminders&&remain.length?`<div class="reminder"><strong>Next check-in</strong><p>${!s.sleep.length?'Sleep is not logged yet.':s.daily.steps===undefined?'Would you like to log today’s steps?':'Would you like to log a meal today?'}</p></div>`:`<div class="reminder"><strong>Your rhythm is taking shape.</strong><p>Keep what works. Adjust what doesn’t.</p></div>`}<p class="note">${esc(s.daily.intention||s.daily.reflection||'What’s one choice you want to repeat tomorrow?')}</p></article>
  </div></section>
 </div>`;
}
function clock12(time){const[h,m]=time.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'am':'pm'}`;}
function timerDuration(minutes){const seconds=Math.floor(Math.max(0,minutes)*60);return `${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function duration(minutes){return `${Math.floor(minutes/60)}h ${Math.floor(minutes%60)}m`;}
function weightChart(){const ws=state.weights.slice().sort((a,b)=>a.date.localeCompare(b.date));if(!ws.length)return `<div class="chart-empty"><div class="chart-grid"></div><span>Your first weight entry starts the chart.</span></div>`;const range=Math.max(2,Math.max(...ws.map(w=>w.kg))-Math.min(...ws.map(w=>w.kg)));const min=Math.min(...ws.map(w=>w.kg))-range*.2;const max=Math.max(...ws.map(w=>w.kg))+range*.2;const first=Date.parse(ws[0].date);const span=Math.max(86400000,Date.parse(ws.at(-1).date)-first);const point=w=>[35+(Date.parse(w.date)-first)/span*520,125-(w.kg-min)/(max-min)*100];const points=ws.map(point);return `<svg class="weight-chart" viewBox="0 0 590 170" role="img" aria-label="Weight trend: ${ws.map(w=>dateLabel(w.date)+' '+w.kg+' kilograms').join(', ')}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4D9A6B" stop-opacity=".4"/><stop offset="1" stop-color="#4D9A6B" stop-opacity="0"/></linearGradient></defs>${[35,80,125].map(y=>`<path d="M35 ${y}H555" stroke="#e4e8dc" stroke-dasharray="4 4"/>`).join('')}<path d="M${points.map(p=>p.join(',')).join(' L')} L${points.at(-1)[0]},135 L35,135 Z" fill="url(#chart-fill)"/><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#14684E" stroke-width="3"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#14684E"><title>${ws[i].date}: ${ws[i].kg} kg</title></circle>`).join('')}<text x="35" y="158">${dateLabel(ws[0].date)}</text><text x="555" y="158" text-anchor="end">${dateLabel(ws.at(-1).date)}</text></svg>`;}
function trendsView(){const w=periodSummary(state),m=periodSummary(state,dayKey(),30);const latest=state.weights.filter(r=>r.date<=dayKey()).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);const current=latest?.kg??state.settings.startWeight;const change=n=>n===null?'More entries needed':`${n>0?'+':''}${fmt(n,1)} kg`;const last7=Array.from({length:7},(_,i)=>shiftDay(dayKey(),i-6));const item=(label,value,note)=>`<div class="trend-metric"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`;
return `${heading('Progress, in perspective.','See what’s working across your food, activity, and rest.')}<section class="card"><div class="card-title"><h2>${icon('weight')} Weight over time</h2>${button('Log weight +','new:weights','secondary')}</div>${weightChart()}<div class="trend-grid">${item('Past 7 days',change(weightChange(state,7)),'Compared with a log on or before 7 days ago')}${item('Past 30 days',change(weightChange(state,30)),'Compared with a log on or before 30 days ago')}${item('Since your start',latest?change(current-state.settings.startWeight):'Waiting for first entry',`${state.settings.startWeight} kg starting reference`)}${item('Long-term direction',`${state.settings.goalWeight} kg`,'An editable personal aspiration')}</div></section><div class="section-heading"><h2>This week’s rhythms</h2><span>${dateLabel(w.start)} – ${dateLabel(w.end)}</span></div><section class="card"><div class="trend-grid">${item('Average calories',w.avgCalories===null?'—':`${fmt(w.avgCalories)} kcal`,'Per day with meal logs · estimates')}${item('Average protein',w.avgProtein===null?'—':`${fmt(w.avgProtein,1)} g`,'Per day with meal logs')}${item('Days with meal logs',`${w.mealDays} / 7`,'Awareness adds up')}${item('Post-meal movement',`${w.walks} sessions`,'Walks and other movement')}${item('Average steps',w.avgSteps===null?'—':fmt(w.avgSteps),'Per day with a step entry')}${item('Exercise',`${w.exerciseMinutes} min`,'Total logged minutes')}${item('Strength training',`${w.strength} sessions`,'Sessions marked as strength')}${item('Average sleep',w.avgSleep===null?'—':duration(w.avgSleep),'Per night with a sleep entry')}${item('Water reference met',`${w.waterDays} / 7 days`,`${fmt(state.settings.waterGoal)} ml personal reference`)}${item('Fasting records',`${w.fastDays} / 7 days`,'Completed records · no duration rewards')}</div></section><section class="card rhythm-card"><h2>Activity & rest over the week</h2><p class="muted">Manual entries; a dash means no log. Sleep is assigned to your waking date.</p><div class="trend-table-wrap"><table class="trend-table"><thead><tr><th scope="col">Day</th><th scope="col">Steps</th><th scope="col">Exercise</th><th scope="col">Sleep</th></tr></thead><tbody>${last7.map(d=>{const t=summary(state,d);return `<tr><th scope="row">${dateLabel(d)}</th><td>${t.daily.steps===undefined?'—':fmt(t.daily.steps)}</td><td>${t.exercise.length?t.exerciseMinutes+' min':'—'}</td><td>${t.sleep.length?duration(t.sleep.at(-1).minutes):'—'}</td></tr>`;}).join('')}</tbody></table></div></section><section class="card rhythm-card"><h2>Seven days of showing up</h2><p class="muted">Meal, water, steps, exercise, sleep, sugar awareness, and post-meal movement logs.</p><div class="week-rhythm">${last7.map(d=>{const s=summary(state,d);return `<div><span>${new Intl.DateTimeFormat('en',{weekday:'short',timeZone:'Asia/Kolkata'}).format(new Date(d+'T12:00:00+05:30'))}</span><div class="day-circle ${s.completed?'filled':''}">${s.completed}<small>/7</small></div><small>${dateLabel(d)}</small></div>`;}).join('')}</div><div class="fast-week"><span>Optional fasting records</span>${last7.map(d=>`<span title="${d}">${state.fasts.some(f=>f.date===d)?'✓':'·'}</span>`).join('')}</div></section><div class="section-heading"><h2>A longer perspective</h2>${button('Edit aspirations','goals','text-button')}</div><section class="card"><p class="muted">Your three-month aspiration is ${state.settings.checkpoints[2]} kg, compared with your ${state.settings.startWeight} kg starting reference. Checkpoints are flexible, never a pass or fail. Choose a pace that suits you.</p><div class="checkpoint-grid">${state.settings.checkpoints.map((kg,i)=>{const cutoff=monthDeadline(state.settings.startDate,i+1);const checkpointWeight=state.weights.filter(w=>w.date<=cutoff&&w.date>=state.settings.startDate).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);return `<div><span>MONTH ${i+1} · ${dateLabel(cutoff)}</span><strong>${kg}<small> kg</small></strong><p>Personal checkpoint</p><p>${checkpointWeight?`Latest log ${dateLabel(checkpointWeight.date)}: ${checkpointWeight.kg} kg · ${fmt(Math.abs(checkpointWeight.kg-kg),1)} kg ${checkpointWeight.kg>=kg?'above':'below'} this reference`:'No weight entry for this period yet.'}</p></div>`;}).join('')}</div><p class="note">${latest?`Latest weight: ${current} kg. ${fmt(Math.abs(current-state.settings.goalWeight),1)} kg ${current>=state.settings.goalWeight?'above':'below'} your long-term reference. ${fmt(Math.abs(current-state.settings.checkpoints[2]),1)} kg ${current>=state.settings.checkpoints[2]?'above':'below'} your month-three reference.`:'Your first weight log will begin this comparison.'}</p></section><section class="card monthly-card"><h2>Your past 30 days</h2><div class="trend-grid">${item('Meal-log days',`${m.mealDays} / 30`,'An incomplete log is still useful')}${item('Average calories',m.avgCalories===null?'—':`${fmt(m.avgCalories)} kcal`,'Based only on logged days')}${item('Average protein',m.avgProtein===null?'—':`${fmt(m.avgProtein,1)} g`,'Based only on logged days')}${item('Post-meal movement',`${m.walks} sessions`,'Logged movement')}${item('Strength sessions',m.strength,'From your exercise logs')}${item('Water reference met',`${m.waterDays} / 30`,'Your editable personal reference')}</div><p class="note">Repeat what works. Use the gaps to plan your next check-in.</p></section>`;}
const names={meals:'Meal',water:'Water',exercise:'Exercise',sleep:'Sleep',weights:'Weight',fasts:'Fast',cravings:'Craving / snack',movements:'Post-meal movement',daily:'Daily check-in'};
function recordText(k,r){if(k==='meals')return `${r.calories} kcal · ${r.protein} g protein${r.fiber!==null?' · '+r.fiber+' g fiber':''}`;if(k==='water')return `${r.amount} ml`;if(k==='weights')return `${r.kg} kg${r.waist?' · Waist '+r.waist+' cm':''}`;if(k==='fasts')return `${duration(elapsedMinutes(r.start,r.end))} · ${new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'}).format(new Date(r.start))} → ${new Intl.DateTimeFormat('en-IN',{timeStyle:'short',timeZone:'Asia/Kolkata'}).format(new Date(r.end))}`;if(k==='sleep'&&r.stages&&Object.keys(r.stages).length)return `${r.minutes} min${r.quality?' · '+r.quality:''} · Manual stages: ${Object.entries(sleepStageNames).filter(([key])=>Object.hasOwn(r.stages,key)).map(([key,name])=>name+' '+r.stages[key]+' min').join(', ')}`;if(k==='cravings')return `Intensity ${r.intensity}/5${r.unplanned?' · Unplanned snack observation':''}`;if(k==='daily')return [r.steps!==undefined&&r.steps+' steps',r.sugar!==undefined&&(r.sugar?'No added sugar checked':'Sugar awareness noted'),r.energy&&'Energy '+r.energy+'/5',r.hunger&&'Hunger '+r.hunger+'/5',r.intention,r.reflection,r.sugarNote].filter(Boolean).join(' · ');return `${r.minutes} min${r.type?' · '+r.type:''}${r.strength?' · Strength session':''}${r.quality?' · '+r.quality:''}`;}
function historyView(){const rows=kinds.flatMap(k=>state[k].map(r=>({...r,kind:k}))).concat(Object.entries(state.days).map(([date,d])=>({...d,date,id:date,kind:'daily'}))).filter(r=>(historyKind==='all'||r.kind===historyKind)&&(!historyDate||r.date===historyDate)).sort((a,b)=>b.date.localeCompare(a.date)||(b.time||'').localeCompare(a.time||''));return `${heading('Your progress, recorded.','Review your entries. Update them whenever you need.')}<div class="history-filters"><label>Show<select id="history-kind"><option value="all">All entries</option>${Object.entries(names).map(([k,v])=>`<option value="${k}" ${historyKind===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Date<input type="date" id="history-date" value="${historyDate}" max="${dayKey()}"></label>${button('Clear filters','clear-filters','text-button')}${button('Add an entry +','add-entry','primary')}</div><section class="card history-list">${rows.length?rows.map(r=>`<article class="history-row"><span class="history-date">${dateLabel(r.date)}<small>${esc(r.time||'')}</small></span><div class="history-copy"><span class="eyebrow">${names[r.kind]}</span><h3>${esc(r.name||r.type||names[r.kind])}</h3><p>${esc(recordText(r.kind,r))}</p>${r.note?`<p class="note">${esc(r.note)}</p>`:''}${r.photo?`<img class="history-photo" src="${r.photo}" alt="${esc(r.name)} attachment">`:''}</div><div class="history-actions">${button('Edit',`edit:${r.kind}`,'text-button',`data-id="${r.id}"`)}${button('Delete',`delete:${r.kind}`,'text-button danger',`data-id="${r.id}"`)}</div></article>`).join(''):`<div class="empty-meals">${icon('history')}<h3>Your journal starts here.</h3><p>No entries match this view. Log an entry or adjust the filters.</p></div>`}</section>`;}
function settingsView(){return `${heading('Make it yours.','Your goals, reminders, and private backups.')}<section class="settings-grid"><article class="card">${cardTitle('Your personal references','weight',button('Edit','goals','text-button'))}<dl class="settings-list"><div><dt>Starting weight</dt><dd>${state.settings.startWeight} kg</dd></div><div><dt>Long-term direction</dt><dd>${state.settings.goalWeight} kg</dd></div><div><dt>Daily step goal</dt><dd>${fmt(dailyStepGoal(state.settings))} steps</dd></div><div><dt>Daily water reference</dt><dd>${fmt(state.settings.waterGoal)} ml</dd></div><div><dt>Daily protein reference</dt><dd>${state.settings.proteinGoal} g</dd></div><div><dt>Eating window</dt><dd>${clock12(state.settings.eatingStart)} – ${clock12(state.settings.eatingEnd)}</dd></div><div><dt>Monthly aspirations</dt><dd>${state.settings.checkpoints.join(' / ')} kg</dd></div></dl><p class="source-label">Optional personal aspirations, not medical recommendations. Results and timing vary.</p></article><article class="card">${cardTitle('In-app reminders','sun')}<label class="toggle-line"><span><strong>Missing-entry prompts</strong><small>Only while you’re using the app.</small></span><input type="checkbox" id="reminders-toggle" ${state.settings.reminders?'checked':''}><span class="toggle" aria-hidden="true"></span></label><label class="toggle-line"><span><strong>Optional fasting reference</strong><small>Show the eating window and planned duration in your journal.</small></span><input type="checkbox" id="fasting-toggle" ${state.settings.fastingOptional?'checked':''}><span class="toggle" aria-hidden="true"></span></label><p class="muted">No notifications are sent while the app is closed.</p></article><article class="card">${cardTitle('Privacy & backups','shield')}<p>Your logs and photos stay in this browser’s IndexedDB on this device. No account, analytics, ads, or health-data uploads.</p><p class="note">Clearing browser or site data can erase your logs. Export a backup before changing phones or browsers. Backup files include your photos and health information; keep them somewhere private.</p><div class="button-row">${button('Export JSON backup','export','primary')}<label class="button secondary file-button">Import backup<input id="import-file" type="file" accept=".json,application/json"></label></div><p id="storage-info" class="source-label">Photos are compressed before saving. Back up regularly.</p>${button('Request persistent storage','persist-storage','text-button')}<hr>${button('Reset all local data','reset','text-button danger')}</article><article class="card">${cardTitle('On your iPhone','today')}<ol class="install-list"><li>Open the published site in <strong>Safari</strong>.</li><li>Tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>.</li><li>Tap <strong>Add</strong>. Steadily is ready for your daily check-in.</li></ol><p class="muted">After one online visit, the installed app works offline for normal tracking. Home Screen and browser storage can differ; export and import a backup if your logs don’t appear.</p><p id="offline-status" class="source-label">Offline shell: checking…</p></article><article class="card">${cardTitle('Quick-add foods','food',button('Edit foods','foods-settings','text-button'))}<p>${state.settings.foods.map(f=>esc(f.name)).join(' · ')}</p><p class="source-label">Starter values are editable estimates per serving. Adjust portions and numbers to match your food. Photos are attachments; no automatic nutrition analysis is configured.</p></article><article class="card">${cardTitle('Your data connections','settings')}<p><strong>Apple Health / Apple Watch</strong></p><p class="muted">Steps, exercise, and sleep are manually entered. This web app cannot directly read Apple Health. The data model includes a source field for a future native companion or shortcut import.</p><p class="source-label">Time zone: Asia/Kolkata · kg · grams · milliliters<br>Steadily v1.0 · Personal wellness, not diagnosis or treatment.</p></article></section>`;}
function render(){const focused=document.activeElement?.id;const mainScroll=$('#main')?.scrollTop||0;$('#app').innerHTML=shell();if(focused&&$('#'+focused))$('#'+focused).focus();if($('#main'))$('#main').scrollTop=mainScroll;tick();if(view==='settings'){navigator.storage?.estimate?.().then(s=>{if($('#storage-info'))$('#storage-info').textContent=`Using ${fmt((s.usage||0)/1048576,1)} MB of browser storage. Photos are compressed before saving.`;});navigator.serviceWorker?.getRegistration().then(r=>{if($('#offline-status'))$('#offline-status').textContent=r?.active?'Offline shell ready.':'Offline shell is preparing; keep this page open briefly while online.';});}}
function tick(){
 const p=fastingProgress(state);
 if($('#fast-clock'))$('#fast-clock').textContent=p.active?timerDuration(p.elapsed):'—';
 const track=$('.fast-plan-track');
 if(track){track.setAttribute('aria-valuenow',String(Math.floor(p.percent)));track.setAttribute('aria-valuetext',p.active&&p.target?Math.floor(p.percent)+'% of planned duration':'No active planned fast');}
 if($('#fast-progress-fill'))$('#fast-progress-fill').style.width=p.percent+'%';
 if($('#fast-plan-note')){const copy=fastPlanCopy(p);if($('#fast-plan-note').textContent!==copy)$('#fast-plan-note').textContent=copy;}
 const el=$('#movement-live');if(el&&state.activeMovement){const a=state.activeMovement;const remaining=Math.max(0,a.minutes*60-Math.floor(elapsedMinutes(a.start)*60));el.innerHTML=`<div class="timer-banner"><span>${esc(a.type)} · <strong>${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}</strong> ${remaining===0?'Time is up. Mark complete when ready.':''}</span>${button('Complete','movement-complete','secondary')}${button('Cancel','movement-cancel','text-button')}</div>`;}else if(el)el.innerHTML='';}
const textField=(label,name,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='text'?'maxlength="2000"':''} ${attrs}></label>`;
const numField=(label,name,value,min,max,step='1',required=true)=>textField(label,name,value,'number',`min="${min}" max="${max}" step="${step}" ${required?'required':''}`);
const area=(label,name,value='')=>`<label>${label}<textarea name="${name}" rows="2" maxlength="2000">${esc(value)}</textarea></label>`;
const select=(label,name,options,value)=>`<label>${label}<select name="${name}">${options.map(o=>`<option value="${esc(o)}" ${value===o?'selected':''}>${esc(o||'Not specified')}</option>`).join('')}</select></label>`;
const dateFields=r=>`<div class="form-row">${textField('Date (Asia/Kolkata)','date',r.date||selectedDay,'date',`required max="${dayKey()}"`)}${textField('Time','time',r.time||timeKey(),'time','required')}</div>`;
function modal(title,body,context=null,submit='Save entry'){dialogContext=context;const d=$('#editor');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button type="button" data-action="close" class="close-button" aria-label="Close dialog">×</button></div><form id="entry-form">${body}<p id="form-error" class="form-error" role="alert"></p>${context?`<div class="dialog-actions">${button('Cancel','close','secondary','type="button"')}<button class="primary" type="submit">${submit}</button></div>`:''}</form>`;if(!d.open)d.showModal();}
function openEntry(kind,id,prefill={}){const r=id?state[kind].find(r=>r.id===id):{...prefill};if(!r){toast('Entry not found.');return;}let body=dateFields(r);if(kind==='meals'){body+=`${textField('Meal name','name',r.name||'Lunch','text','required maxlength="100"')}<p class="source-label">Calories and nutrition are manually entered estimates. Photo analysis is not configured.</p>${area('Food description','description',r.description)}${textField('Portion description','portion',r.portion||'')}<div class="form-row">${numField('Calories (kcal)','calories',r.calories??'',0,10000,.1)}${numField('Protein (g)','protein',r.protein??'',0,1000,.1)}${numField('Fiber (g, optional)','fiber',r.fiber??'',0,500,.1,false)}</div><label>Photo attachment (optional)<input type="file" name="photo" accept="image/*"></label><p class="source-label">Choose Camera or Photo Library on iPhone. Compressed to at most 1,000 pixels; attachment only.</p>${r.photo?`<img src="${r.photo}" class="form-photo" alt="Current meal attachment"><label class="check-label"><input type="checkbox" name="removePhoto">Remove photo</label>`:''}<label class="check-label"><input type="checkbox" name="favorite" ${r.favorite?'checked':''}>Save as a favorite meal</label>`;}
if(kind==='water')body+=numField('Water (ml)','amount',r.amount??250,1,5000);
if(kind==='exercise')body+=`<p class="source-label">Manually entered from Apple Health / Apple Watch.</p>${textField('Exercise type','type',r.type||'Walk','text','required')}${numField('Duration (minutes)','minutes',r.minutes??30,1,1440)}<label class="check-label"><input type="checkbox" name="strength" ${r.strength?'checked':''}>This was a strength-training session</label>`;
if(kind==='sleep')body+=`<p class="source-label">Manually entered from Apple Health / Apple Watch. Save the previous night’s sleep under your waking date.</p><div class="form-row">${numField('Hours','hours',r.minutes===undefined?7:Math.floor(r.minutes/60),0,24)}${numField('Minutes','minutes',r.minutes===undefined?0:r.minutes%60,0,59)}</div>${select('Sleep quality (optional)','quality',['','poor','fair','good','excellent'],r.quality||'')}<fieldset class="stage-fields"><legend>Optional sleep stages</legend><p class="source-label">Manually enter stage minutes from Apple Health / Apple Watch. Leave unknown stages blank. Sleep duration above means time asleep; Awake is additional time.</p><div class="form-row">${Object.entries(sleepStageNames).map(([key,name])=>numField(name+' (minutes, optional)','stage_'+key,r.stages?.[key]??'',0,1440,1,false)).join('')}</div></fieldset>`;
if(kind==='weights')body+=`${numField('Weight (kg)','kg',r.kg??state.weights.at(-1)?.kg??state.settings.startWeight,20,500,.1)}${numField('Waist (cm, optional weekly measurement)','waist',r.waist??'',20,300,.1,false)}`;
if(kind==='cravings')body+=`${numField('Craving intensity (1 gentle → 5 strong)','intensity',r.intensity??3,1,5)}<label class="check-label"><input type="checkbox" name="unplanned" ${r.unplanned?'checked':''}>Unplanned snack observation</label><p class="source-label">Notice the craving. Capture what was happening.</p>`;
if(kind==='movements')body+=`${textField('Movement type (walk, squats, light exercise, or custom)','type',r.type||'Walk','text','required')}${numField('Duration (minutes)','minutes',r.minutes??10,1,1440)}`;
if(kind==='fasts'){body=`<p class="source-label">Optional history, with no rewards for duration. All times are Asia/Kolkata.</p>${textField('Start','start',r.start?dayKey(new Date(r.start))+'T'+timeKey(new Date(r.start)):selectedDay+'T21:00','datetime-local','required')}${textField('End','end',r.end?dayKey(new Date(r.end))+'T'+timeKey(new Date(r.end)):dayKey()+'T'+timeKey(),'datetime-local','required')}`;}
body+=area('Notes (optional)','note',r.note);modal((id?'Edit ':'Log ')+names[kind].toLowerCase(),body,{kind,id,original:r});}
function openDaily(kind,id){const day=id||selectedDay;const d=state.days[day]||{};let body=textField('Date (Asia/Kolkata)','date',day,'date',`required max="${dayKey()}"`);if(kind==='steps'||kind==='daily')body+=`<p class="source-label">Steps: manually entered from Apple Health / Apple Watch.</p>${numField('Steps (leave blank to remove)','steps',d.steps??'',0,100000,1,false)}`;
if(kind==='sugar-note'||kind==='daily')body+=`${select('Added sugar awareness','sugar',['Not checked in','No added sugar today','Awareness noted'],d.sugar===undefined?'Not checked in':d.sugar?'No added sugar today':'Awareness noted')}${area('Sugar awareness note (optional)','sugarNote',d.sugarNote)}`;
if(kind==='morning'){const yesterday=summary(state,shiftDay(day,-1));body+=`<div class="form-summary"><strong>Yesterday’s summary</strong><p>${yesterday.meals.length} meals · ${fmt(yesterday.calories)} kcal · ${fmt(yesterday.protein,1)} g protein · ${fmt(yesterday.waterTotal)} ml water · ${yesterday.daily.steps??'—'} steps</p><p>${state.activeFast?'Current fast: '+duration(elapsedMinutes(state.activeFast.start)):'No fast in progress.'}</p></div>`;}
if(kind==='morning'||kind==='daily')body+=area('Today’s weight, food, and activity intentions (optional)','intention',d.intention);
if(kind==='evening'){const s=summary(state,day);body+=`<div class="form-summary"><strong>Your day so far</strong><p>${s.meals.length} meals · ${fmt(s.waterTotal)} ml water · ${s.exerciseMinutes} exercise minutes · ${s.completed} of ${s.habitCount} areas logged.</p><p>${[!s.meals.length&&'Meals are not logged yet.',!s.sleep.length&&'Sleep is not logged yet.',s.daily.steps===undefined&&'Would you like to log today’s steps?',!s.exercise.length&&'Exercise has not been logged.',!s.water.length&&'Water has not been logged.',s.daily.sugar===undefined&&'Sugar awareness has not been checked in.',!s.movements.length&&'Post-meal movement has not been logged.'].filter(Boolean).join(' ')||'All seven areas have an entry.'}</p></div>`;}
if(kind==='evening'||kind==='daily')body+=`<div class="form-row">${numField('Energy (1–5, optional)','energy',d.energy??'',1,5,1,false)}${numField('Hunger (1–5, optional)','hunger',d.hunger??'',1,5,1,false)}</div>${area('Evening reflection (optional)','reflection',d.reflection)}`;
modal(kind==='morning'?'Morning overview':kind==='evening'?'Evening review':'Daily check-in',body,{kind:'daily',mode:kind,originalDate:day});}
function goals(){const s=state.settings;modal('Your personal references',`<p class="muted">Flexible aspirations, never pass or fail. Water, protein, weight, and eating-window references are your choices.</p><div class="form-row">${numField('Starting weight (kg)','startWeight',s.startWeight,20,500,.1)}${numField('Long-term goal (kg)','goalWeight',s.goalWeight,20,500,.1)}</div>${textField('Journey start date','startDate',s.startDate,'date','required')}<div class="form-row">${numField('Daily step goal','stepGoal',dailyStepGoal(s),1,100000)}${numField('Water reference (ml)','waterGoal',s.waterGoal,250,10000)}${numField('Protein reference (g)','proteinGoal',s.proteinGoal,1,500)}</div><div class="form-row">${s.checkpoints.map((v,i)=>numField(`Month ${i+1} (kg)`,`month${i}`,v,20,500,.1)).join('')}</div><div class="form-row">${textField('Eating window starts','eatingStart',s.eatingStart,'time','required')}${textField('Eating window ends','eatingEnd',s.eatingEnd,'time','required')}</div>`,{kind:'goals'},'Save references');}
function movement(mealId){modal('A moment to move',`<p>Would you like to complete a 10-minute post-meal walk?</p>${textField('Movement type','type','Walk','text','required')}<div class="movement-options">${button('Start 10-minute timer','timer:10','primary','type="button"')}${button('Start 15-minute timer','timer:15','secondary','type="button"')}${button('Mark completed manually','manual-movement','secondary','type="button"')}${button('Skip for now','close','text-button','type="button"')}</div><p class="source-label">A simple habit log. The timer stays accurate if the app is backgrounded; it does not send closed-app notifications.</p>`,null);dialogContext={kind:'movement-prompt',mealId};}
function foodList(edit=false){if(edit){modal('Your quick-add foods',`<div class="food-editor">${state.settings.foods.map((f,i)=>`<fieldset><legend>Food ${i+1}</legend>${textField('Name',`name${i}`,f.name,'text','required maxlength="100"')}${textField('Portion',`portion${i}`,f.portion,'text','required maxlength="200"')}<div class="form-row">${numField('kcal',`cal${i}`,f.calories,0,10000,.1)}${numField('Protein g',`pro${i}`,f.protein,0,1000,.1)}${numField('Fiber g',`fib${i}`,f.fiber,0,500,.1)}</div></fieldset>`).join('')}</div><p class="source-label">Values are manually entered estimates.</p>`,{kind:'foods'},'Save foods');}else modal('Quick-add foods',`<p class="muted">Choose a food, then adjust its serving and estimated nutrition.</p><div class="food-choice-list">${state.settings.foods.map((f,i)=>button(`<strong>${esc(f.name)}</strong><span>${f.calories} kcal · ${f.protein} g protein</span>`,`food:${i}`,'food-choice','type="button"')).join('')}</div>`);}
function mealTemplates(favorites){const meals=state.meals.filter(m=>!favorites||m.favorite).slice().reverse();const unique=[...new Map(meals.map(m=>[m.name+'|'+m.calories,m])).values()].slice(0,15);modal(favorites?'Favorite meals':'Recent meals',unique.length?`<p class="muted">Use a saved meal as a starting point. Adjust estimates before saving.</p><div class="food-choice-list">${unique.map(m=>button(`<strong>${esc(m.name)}</strong><span>${m.calories} kcal · ${m.protein} g protein</span>`,'template','food-choice',`type="button" data-id="${m.id}"`)).join('')}</div>`:'<p class="muted">Log a meal first. You can mark any meal as a favorite.</p>');}
function close(){if($('#editor').open)$('#editor').close();dialogContext=null;}
async function handleAction(action,el){const [verb,arg]=action.split(':');if(verb==='close'){close();return;}if(verb==='new'){openEntry(arg);return;}if(verb==='edit'){arg==='daily'?openDaily('daily',el.dataset.id):openEntry(arg,el.dataset.id);return;}
if(verb==='delete'){const id=el.dataset.id;modal('Delete this entry?',`<p>This removes the selected ${names[arg].toLowerCase()} from this device. Export a backup first if you want to keep a copy.</p>`,{kind:'delete',collection:arg,id},'Delete entry');return;}
if(verb==='water'){await commit(s=>s.water.push({id:crypto.randomUUID(),date:selectedDay,time:timeKey(),amount:Number(arg),source:'manual'}));toast('Logged — one step done.');return;}
if(verb==='water-undo'){const last=state.water.filter(r=>r.date===selectedDay).at(-1);if(last&&await commit(s=>{s.water=s.water.filter(r=>r.id!==last.id);}))toast('Latest water entry undone.');return;}
if(verb==='favorite'){await commit(s=>{const m=s.meals.find(m=>m.id===el.dataset.id);m.favorite=!m.favorite;});return;}
if(verb==='step-goal'){modal('Your daily step goal',`${numField('Daily step goal','stepGoal',dailyStepGoal(state.settings),1,100000)}<p class="source-label">A personal reference, not a prescription. The initial reference is 8,000 steps and can be changed. It does not affect your consistency score.</p>`,{kind:'step-goal'},'Save step goal');return;}
if(verb==='fast-schedule'){modal('Your fasting schedule',`<p class="muted">Edit your eating window. The time outside it defines your optional fasting plan.</p><div class="form-row">${textField('Eating window starts','eatingStart',state.settings.eatingStart,'time','required')}${textField('Eating window ends','eatingEnd',state.settings.eatingEnd,'time','required')}</div><label class="check-label"><input type="checkbox" name="fastingOptional" ${state.settings.fastingOptional?'checked':''}>Show eating window and planned duration</label><p class="source-label">${state.activeFast?'Saving also updates the current fast’s planned duration. ':''}You can end a fast early. Matching start/end times mean no duration target. Times are Asia/Kolkata.</p>`,{kind:'fast-schedule'},'Save schedule');return;}
if(verb==='goals'){goals();return;}if(['steps','morning','evening','sugar-note'].includes(verb)){openDaily(verb);return;}if(verb==='foods'||verb==='foods-settings'){foodList(verb==='foods-settings');return;}
if(verb==='food'){const f=state.settings.foods[Number(arg)];openEntry('meals',null,{...f,name:f.name});return;}
if(verb==='recent'||verb==='favorites'){mealTemplates(verb==='favorites');return;}
if(verb==='template'){const m=state.meals.find(m=>m.id===el.dataset.id);openEntry('meals',null,{...m,id:undefined,date:selectedDay,time:timeKey(),photo:null});return;}
if(verb==='movement'){movement();return;}
if(verb==='timer'){if(state.activeMovement){toast('Complete or cancel your current movement timer first.');return;}const type=$('#entry-form input[name="type"]').value.trim()||'Walk';const mealId=dialogContext?.mealId;const start=new Date().toISOString();if(await commit(s=>{s.activeMovement={start,minutes:Number(arg),type,date:selectedDay,mealId:mealId||null};})){close();toast('Timer started. Move comfortably.');}return;}
if(verb==='manual-movement'){const type=$('#entry-form input[name="type"]').value;openEntry('movements',null,{type,minutes:10,mealId:dialogContext?.mealId});return;}
if(verb==='movement-complete'){const a=state.activeMovement;if(a&&await commit(s=>{s.movements.push({id:crypto.randomUUID(),date:a.date,time:timeKey(),type:a.type,minutes:a.minutes,mealId:a.mealId,note:'',source:'timer'});s.activeMovement=null;}))toast('Movement logged — one step done.');return;}
if(verb==='movement-cancel'){await commit(s=>{s.activeMovement=null;});return;}
if(verb==='fast-edit'){modal('Edit active fast',`${textField('Start time (Asia/Kolkata)','start',dayKey(new Date(state.activeFast.start))+'T'+timeKey(new Date(state.activeFast.start)),'datetime-local','required')}`,{kind:'fast-edit'},'Save start');return;}
if(verb==='fast-start'){modal('Start a fast',`${textField('Start time (Asia/Kolkata)','start',dayKey()+'T'+timeKey(),'datetime-local','required')}<p class="muted">${state.settings.fastingOptional&&fastingPlanMinutes(state.settings)?'Planned duration: '+duration(fastingPlanMinutes(state.settings))+'. ':''}Fasting is optional. You can end early; duration does not affect your consistency score.</p>`,{kind:'fast-start'},'Start fast');return;}
if(verb==='fast-end'){const a=state.activeFast;if(a)modal('End your fast',`${textField('End time (Asia/Kolkata)','end',dayKey()+'T'+timeKey(),'datetime-local','required')}${area('Notes (optional)','note')}<p class="muted">Started ${dateLabel(dayKey(new Date(a.start)))} at ${timeKey(new Date(a.start))}.</p>`,{kind:'fast-end'},'Save completed fast');return;}
if(['fast-history','water-history'].includes(verb)){view='history';historyKind=verb==='fast-history'?'fasts':'water';historyDate=verb==='water-history'?selectedDay:'';render();return;}
if(verb==='clear-filters'){historyDate='';historyKind='all';render();return;}
if(verb==='add-entry'){modal('Add an entry',`<div class="food-choice-list">${kinds.map(k=>button(names[k],`new:${k}`,'food-choice','type="button"')).join('')}${button('Daily check-in','steps','food-choice','type="button"')}</div>`);return;}
if(verb==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`steadily-backup-${dayKey()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Backup exported. Keep it somewhere private.');return;}
if(verb==='reset'){modal('Reset all local data?',`<p>All health logs, photos, timers, favorites, and settings will be removed from this browser. Export a backup first.</p>${textField('Type RESET to confirm','confirmation','','text','required pattern="RESET"')}`,{kind:'reset'},'Reset all data');return;}
if(verb==='persist-storage'){const granted=await navigator.storage?.persist?.();toast(granted?'Persistent storage granted. Keep exporting backups too.':'Your browser decides storage retention. Regular exports are the best backup.');return;}}
async function submit(event){event.preventDefault();if(!dialogContext)return;const ctx=dialogContext;const form=event.target;const submitButton=form.querySelector('[type="submit"]');submitButton.disabled=true;$('#form-error').textContent='';const f=new FormData(form);const val=k=>String(f.get(k)??'').trim();const n=k=>val(k)===''?null:Number(val(k));const bool=k=>f.has(k);let promptMeal;
try {const ok=await commit(async s=>{
 if(ctx.kind==='delete'){if(ctx.collection==='daily')delete s.days[ctx.id];else s[ctx.collection]=s[ctx.collection].filter(r=>r.id!==ctx.id);return;}
 if(ctx.kind==='reset'){if(val('confirmation')!=='RESET')throw Error('Type RESET to confirm.');Object.assign(s,emptyState());return;}
 if(ctx.kind==='import'){Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,ctx.backup);return;}
 if(ctx.kind==='goals'){for(const k of ['startWeight','goalWeight','waterGoal','proteinGoal','stepGoal'])s.settings[k]=n(k);for(const k of ['startDate','eatingStart','eatingEnd'])s.settings[k]=val(k);s.settings.checkpoints=[0,1,2].map(i=>n('month'+i));if(s.activeFast)s.activeFast.plannedMinutes=s.settings.fastingOptional?fastingPlanMinutes(s.settings):null;return;}
 if(ctx.kind==='step-goal'){s.settings.stepGoal=n('stepGoal');return;}
 if(ctx.kind==='fast-schedule'){s.settings.eatingStart=val('eatingStart');s.settings.eatingEnd=val('eatingEnd');s.settings.fastingOptional=bool('fastingOptional');if(s.activeFast)s.activeFast.plannedMinutes=s.settings.fastingOptional?fastingPlanMinutes(s.settings):null;return;}
 if(ctx.kind==='foods'){s.settings.foods=s.settings.foods.map((_,i)=>({name:val('name'+i),portion:val('portion'+i),calories:n('cal'+i),protein:n('pro'+i),fiber:n('fib'+i)}));return;}
 if(ctx.kind==='daily'){const date=val('date');if(date>dayKey())throw Error('Daily logs cannot be in the future.');const d={...(s.days[date]||{})};for(const key of ['steps','energy','hunger'])if(f.has(key)){if(n(key)===null)delete d[key];else d[key]=n(key);}for(const key of ['sugarNote','intention','reflection'])if(f.has(key))d[key]=val(key);if(f.has('sugar')){if(val('sugar')==='Not checked in')delete d.sugar;else d.sugar=val('sugar')==='No added sugar today';}if(ctx.originalDate!==date){const old={...(s.days[ctx.originalDate]||{})};for(const key of ['steps','energy','hunger','sugar','sugarNote','intention','reflection'])if(f.has(key))delete old[key];if(Object.keys(old).length)s.days[ctx.originalDate]=old;else delete s.days[ctx.originalDate];}if(f.has('steps'))d.activitySource='manual';s.days[date]=d;return;}
 if(ctx.kind==='fast-start'||ctx.kind==='fast-edit'){const start=new Date(val('start')+':00+05:30').toISOString();if(Date.parse(start)>Date.now())throw Error('Start time must not be in the future.');if(s.activeFast&&ctx.kind==='fast-start')throw Error('A fast is already active.');s.activeFast={...(ctx.kind==='fast-edit'?s.activeFast:{}),start,source:'manual'};if(ctx.kind==='fast-start')s.activeFast.plannedMinutes=s.settings.fastingOptional?fastingPlanMinutes(s.settings):null;return;}
 if(ctx.kind==='fast-end'){if(!s.activeFast)throw Error('No active fast.');const end=val('end')===dayKey()+'T'+timeKey()?new Date().toISOString():new Date(val('end')+':00+05:30').toISOString();if(Date.parse(end)<=Date.parse(s.activeFast.start))throw Error('End must be after the start.');if(Date.parse(end)>Date.now())throw Error('End time must not be in the future.');s.fasts.push({id:crypto.randomUUID(),date:dayKey(new Date(end)),start:s.activeFast.start,end,note:val('note'),source:'manual',plannedMinutes:fastingProgress(s).target});s.activeFast=null;return;}
 const kind=ctx.kind;const r={...ctx.original,id:ctx.id||crypto.randomUUID(),date:val('date'),time:val('time'),note:val('note'),source:'manual'};
 if(kind==='meals'){Object.assign(r,{name:val('name'),description:val('description'),portion:val('portion'),calories:n('calories'),protein:n('protein'),fiber:n('fiber'),favorite:bool('favorite')});if(bool('removePhoto'))r.photo=null;const file=f.get('photo');if(file?.size)r.photo=await compressPhoto(file);if(!ctx.id)promptMeal=r.id;}
 if(kind==='water')r.amount=n('amount');if(kind==='exercise')Object.assign(r,{type:val('type'),minutes:n('minutes'),strength:bool('strength')});if(kind==='sleep'){r.minutes=n('hours')*60+n('minutes');r.quality=val('quality');const stages={};for(const key of Object.keys(sleepStageNames))if(n('stage_'+key)!==null)stages[key]=n('stage_'+key);if(Object.keys(stages).length)r.stages=stages;else delete r.stages;if(s.sleep.some(x=>x.date===r.date&&x.id!==ctx.id))throw Error('Sleep is already logged for that waking date. Edit the existing sleep entry in History.');}
 if(kind==='weights')Object.assign(r,{kg:n('kg'),waist:n('waist')});if(kind==='cravings')Object.assign(r,{intensity:n('intensity'),unplanned:bool('unplanned')});if(kind==='movements')Object.assign(r,{type:val('type'),minutes:n('minutes')});
 if(kind==='fasts'){r.start=new Date(val('start')+':00+05:30').toISOString();r.end=new Date(val('end')+':00+05:30').toISOString();r.date=dayKey(new Date(r.end));delete r.time;if(Date.parse(r.end)>Date.now())throw Error('Completed fasts cannot end in the future.');}
 if(r.date>dayKey())throw Error('Logs cannot be dated in the future.');if(ctx.id){if(!s[kind].some(x=>x.id===ctx.id))throw Error('This entry was removed in another tab. Close this form and review History.');s[kind]=s[kind].map(x=>x.id===ctx.id?r:x);}else s[kind].push(r);
 });if(ok){close();toast(ctx.kind==='import'?'Backup restored.':ctx.kind==='delete'?'Entry deleted.':ctx.kind.startsWith('fast')?'Fasting record saved.':ctx.id?'Updated — saved on this device.':kinds.includes(ctx.kind)?'Logged — one step done.':ctx.kind==='daily'?'Check-in saved — ready for your next choice.':'Saved on this device.');if(promptMeal)movement(promptMeal);}else $('#form-error').textContent='This entry could not be saved. Check the message below and your values.';
} catch(e){$('#form-error').textContent=e.message;}finally{submitButton.disabled=false;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-view],[data-action]');if(!el)return;if(el.dataset.view){view=el.dataset.view;location.hash=view;render();window.scrollTo({top:0});$('#main')?.scrollTo({top:0});}else handleAction(el.dataset.action,el).catch(err=>toast(err.message));});
document.addEventListener('submit',e=>{if(e.target.id==='entry-form')submit(e);});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='selected-day'){selectedDay=el.value||dayKey();render();}if(el.id==='history-kind'){historyKind=el.value;render();}if(el.id==='history-date'){historyDate=el.value;render();}if(el.id==='sugar-toggle')await commit(s=>{s.days[selectedDay]={...(s.days[selectedDay]||{}),sugar:el.checked};});if(el.id==='reminders-toggle'||el.id==='fasting-toggle')await commit(s=>{s.settings[el.id==='reminders-toggle'?'reminders':'fastingOptional']=el.checked;});if(el.id==='import-file'){const file=el.files[0];if(!file)return;try{if(file.size>100000000)throw Error('Choose a backup smaller than 100 MB.');const backup=parseBackup(await file.text());const count=kinds.reduce((n,k)=>n+backup[k].length,0);modal('Restore this backup?',`<p>This backup contains <strong>${count} entries</strong> and ${Object.keys(backup.days).length} daily check-ins. Restoring replaces all current data on this device, including photos and settings. Export your current data first if you want to keep it.</p>`,{kind:'import',backup},'Replace data & restore');}catch(err){toast('Import rejected: '+err.message);}el.value='';}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['today','trends','history','settings'].includes(v)){view=v;render();}});
window.addEventListener('online',()=>{if($('#connection'))$('#connection').textContent='On this device';});window.addEventListener('offline',()=>{if($('#connection'))$('#connection').textContent='Offline · ready to log';});
async function boot(){try{state=await readState()||emptyState();validateState(state);const v=location.hash.slice(1);if(['today','trends','history','settings'].includes(v))view=v;render();setInterval(()=>{const today=dayKey();if(boot.lastDay!==today){if(selectedDay===boot.lastDay)selectedDay=today;boot.lastDay=today;render();}tick();},1000);boot.lastDay=dayKey();if('serviceWorker'in navigator&&document.querySelector('meta[name=app-mode]')?.content==='production')navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline setup is unavailable here. Use the published HTTPS site.'));}catch(error){$('#app').innerHTML=`<main class="startup-error"><h1>Your journal could not be opened.</h1><p>${esc(error.message)}</p><p>Local storage may be disabled or the stored data may be incompatible. Your existing data has not been replaced. Try your usual browser with site storage enabled.</p></main>`;}}
boot();
